```csharp
using System;

interface IFoo
{
    public void DoWork() => Console.WriteLine("UU");
    internal void OtherWork() => Console.WriteLine("OO");
}

class Base : IFoo
{
    static void Main()
    {
        foreach (var v in typeof(Base).GetInterfaceMap(typeof(IFoo)).TargetMethods)
        {
            Console.WriteLine(v);
        }
    }
}
